set-variable.value:
#[output application/java ---
{
    correlationId: vars.request.correlationId,
    sagaId: vars.request.sagaId,
    stepId: vars.request.stepId,
    stepName: vars.request.stepName default 'RESERVE_INVENTORY',
    commandType: 'RESERVE',
    attempt: vars.request.attempt default 1,
    payload: {
        orderId: vars.request.orderId,
        items: vars.request.items
    }
}]

#[output application/java
var raw = if (payload is String or payload is Binary) read(payload, 'application/json') else (payload default {})
var body = if (raw.payload is String) read(raw.payload, 'application/json') else (raw.payload default raw)
var resolvedItems = if (body.items is String) read(body.items, 'application/json') else (raw.items default body.items default [])
var resolvedOrderId = raw.orderId default body.orderId default null
---
raw ++ {
    correlationId: raw.correlationId default attributes.properties.correlationId default correlationId,
    sagaId: raw.sagaId default body.sagaId default ('SAGA-' ++ (uuid() as String)),
    stepId: raw.stepId default body.stepId default ('STEP-' ++ (uuid() as String)),
    replyTo: raw.replyTo default attributes.properties.replyTo default 'inventory.reserve.reply',
    orderId: resolvedOrderId,
    items: resolvedItems
}]

#[output application/java ---
{
    correlationId: vars.request.correlationId,
    sagaId: vars.request.sagaId,
    stepId: vars.request.stepId,
    stepName: vars.request.stepName default 'RESERVE_INVENTORY',
    commandType: 'RESERVE',
    attempt: vars.request.attempt default 1,
    payload: {
        orderId: vars.request.orderId,
        items: vars.request.items
    }
}]

#[output application/java
var raw = if (payload is String or payload is Binary) read(payload, 'application/json') else (payload default {})
var body = if (raw.payload is String) read(raw.payload, 'application/json') else (raw.payload default raw)
var resolvedOrderId = raw.orderId default body.orderId default null
var resolvedReservationId = raw.reservationId default body.reservationId default null
var resolvedReservationIds = if (body.reservationIds is String) read(body.reservationIds, 'application/json') else (raw.reservationIds default body.reservationIds default [])
---
raw ++ {
    correlationId: raw.correlationId default attributes.properties.correlationId default correlationId,
    sagaId: raw.sagaId default body.sagaId default 'SAGA-UNKNOWN',
    stepId: raw.stepId default body.stepId default 'STEP-UNKNOWN',
    replyTo: raw.replyTo default attributes.properties.replyTo default 'inventory.release.reply',
    orderId: resolvedOrderId,
    reservationId: resolvedReservationId,
    reservationIds: resolvedReservationIds
}]

#[output application/java ---
{
    correlationId: vars.command.correlationId,
    sagaId: vars.command.sagaId,
    stepId: vars.command.stepId,
    stepName: 'RELEASE_INVENTORY',
    attempt: vars.command.attempt default 1,
    outcome: 'SUCCESS',
    completedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"},
    result: (
        {
            reservationIds: vars.releaseIds,
            reservationStatus: 'RELEASED'
        }
        ++
        (
            if (sizeOf(vars.releaseIds) == 1)
                { reservationId: vars.releaseIds[0] }
            else
                {}
        )
    )
}]

db:insert.db:input-parameters:
